 function logRows(floor){const rows=[];for(const [index,frame]of (floor?.frames??[]).entries()){const last=rows.at(-1);if(last&&last.speaker===frame.speaker&&last.location===frame.location)last.frames.push(frame);else rows.push({speaker:frame.speaker,location:frame.location,frames:[frame],index});}const speakers=[...new Set(rows.map(x=>x.speaker).filter(Boolean))];return rows.map(row=>{const side=speakers.indexOf(row.speaker)%2?'right':'left',tone=['rose','lilac','mint','amber'][Math.max(0,speakers.indexOf(row.speaker))%4];return `<article class="gal-log-row ${row.speaker?side:'narrator'}" data-tone="${tone}">${row.speaker?avatarByName.get(row.speaker)?`<img class="gal-log-avatar" src="${esc(avatarByName.get(row.speaker))}" alt="${esc(row.speaker)}">`:`<span class="gal-log-avatar">${esc(row.speaker.slice(0,1))}</span>`:''}<div class="gal-log-copy">${row.speaker?`<strong>${esc(row.speaker)}</strong>`:''}${row.frames.map(frame=>`<p class="log-${frame.kind}">${frame.kind==='语言'?'':`<small>${frame.kind}</small> `}${esc(frame.text)}</p>`).join('')}<button data-replay="${row.index}">从这里回看 ↗</button></div></article>`;}).join('');}
